def countdown(seconds):
    """Count down from the given number of seconds to zero."""
    while seconds > 0:
        print(f"{seconds} seconds remaining...")
        seconds -= 1
    print("Time's up!")

# Get user input for the time interval in seconds
try:
    time_interval = int(input("Enter the time interval in seconds: "))
    if time_interval < 0:
        raise ValueError("Time interval must be non-negative.")
except ValueError as e:
    print(e)
else:
    countdown(time_interval)
```

